Given a function $H : [0,T) \times \Omega \times \mathbb{R}^{n+1} \to \mathbb{R}$, a function $u : [0,T) \times \Omega \to \mathbb{R}$ is called a \emph{viscosity solution} of the differential equation 
$$0 = \frac{d}{d t} u (t,\omega) + H(t, \omega, u(t,\omega), \nabla u(t,\omega))$$
if:
\begin{enumerate}
\item for any $\mathcal C^1$ function $\psi : [0,T) \times \Omega \to \mathbb{R}$ with  $u - \psi$ having a strict local maximum at $(\overline{t}, \overline{\omega}) \in [0,T) \times \Omega$ we have
$0 \le \frac{d}{d t} \psi (\overline{t}, \overline{\omega}) + H(\overline{t}, 
\overline{\omega}, \psi(\overline{t}, \overline{\omega}), \nabla \psi(\overline{t}, \overline{\omega}))$;
\item for any $\mathcal C^1$ function $\psi : [0,T) \times \Omega \to \mathbb{R}$ with 
$u - \psi$ having a strict local minimum at $(\overline{t}, \overline{\omega}) \in 
[0,T) \times \Omega$ we have
$0 \ge \frac{d}{d t} \psi (\overline{t}, \overline{\omega}) + H(\overline{t}, 
\overline{\omega}, \psi(\overline{t}, \overline{\omega}), \nabla \psi(\overline{t}, \overline{\omega}))$.
\end{enumerate}

